<include file="Public:header"/>		<div class="mainbox">			<div id="nav" class="mainnav_title">				<ul>					<a href="{pigcms{:U('index')}" class="on">公共场所防控二维码列表</a>					<a href="javascript:void(0);" onclick="window.top.artiframe('{pigcms{:U('PreventionControl/add')}','添加二维码信息',580,460,true,false,false,addbtn,'add',true);">添加二维码信息</a>				</ul>			</div>			<table class="search_table" width="100%">				<tr>					<td>						<form action="{pigcms{:U('PreventionControl/index')}" method="get">							<input type="hidden" name="c" value="PreventionControl"/>							<input type="hidden" name="a" value="index"/>							名称: 							<input type="text" name="name" class="input-text" value="{pigcms{$_GET['name']}"/>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;							电话: 							<input type="text" name="phone" class="input-text" value="{pigcms{$_GET['phone']}"/>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;							类型: <select name="type">								<option value="-1" <if condition="$_GET['type'] eq -1">selected="selected"</if>>全部</option>								<volist name="type_info" id="vo">									<option value="{pigcms{$key}" <if condition="$_GET['type'] heq $key">selected="selected"</if>>{pigcms{$vo}</option>								</volist>							</select>							<input type="submit" value="查询" class="button"/>														<input type="button" value="用户扫码数据查看" class="button" onclick="location.href='{pigcms{:U('user_list')}'" style="margin-left:100px;"/>						</form>					</td>				</tr>			</table>			<form name="myform" id="myform" action="" method="post">				<div class="table-list">					<style>					.table-list td{line-height:22px;padding-top:5px;padding-bottom:5px;}					</style>					<table width="100%" cellspacing="0">						<colgroup>							<col/>							<col/>							<col/>							<col/>							<col/>							<col width="180" align="center"/>						</colgroup>						<thead>							<tr>								<th>编号</th>								<th>名称</th>								<th>类型</th>								<th>联系电话</th>								<th>关联管理员（ID）</th>								<th>网页二维码</th>								<th>小程序二维码</th>								<th>海报下载</th>								<th>添加时间</th>								<th>二维码填写记录</th>								<th class="textcenter">操作</th>							</tr>						</thead>						<tbody>							<if condition="is_array($list)">								<volist name="list" id="vo">									<tr>										<td>{pigcms{$vo.id}</td>										<td>{pigcms{$vo.name}</td>										<td>{pigcms{$type_info[$vo['type']]}</td>										<td>{pigcms{$vo.phone}</td>										<td>											<if condition="isset($vo['bind_admin_name']) && $vo['bind_admin'] gt 0">												{pigcms{$vo.bind_admin_name}（{pigcms{$vo.bind_admin}）												<else/>												-											</if>										</td>										<td>											<a href="javascript:void(0);" onclick="window.top.artiframe('{pigcms{$vo.qrcode}','查看二维码',400,400,true,false,false,null,'merchant_qrcode',true);" class="see_qrcode">											查看网页二维码											</a>										</td>										<td>											<a href="javascript:void(0);" onclick="window.top.artiframe('{pigcms{$vo.wxapp_qrcode}','查看二维码',427,427,true,false,false,null,'merchant_qrcode',true);" class="see_qrcode">											查看小程序二维码											</a>										</td>										<td>											<a href="{pigcms{:U('PreventionControl/down_img',array('id'=>$vo['id'],'txt_type'=>'0'))}">											文字版											</a>&nbsp;&nbsp;											|&nbsp;&nbsp;											<a href="{pigcms{:U('PreventionControl/down_img',array('id'=>$vo['id'],'txt_type'=>'1'))}">											简洁版											</a>										</td>										<td>{pigcms{$vo.add_time|date='Y-m-d H:i:s',###}</td>										<td>											<a href="{pigcms{:U('PreventionControl/user_index',array('id'=>$vo['id']))}">											查看填写记录											</a>										</td>										<td class="textcenter"><a href="javascript:void(0);" onclick="window.top.artiframe('{pigcms{:U('PreventionControl/edit',array('id'=>$vo['id'],'frame_show'=>true))}','查看信息',550,450,true,false,false,false,'detail',true);">查看</a> | <a href="javascript:void(0);" onclick="window.top.artiframe('{pigcms{:U('PreventionControl/edit',array('id'=>$vo['id']))}','编辑',550,450,true,false,false,editbtn,'edit',true);">编辑</a> </td>									</tr>								</volist>								<tr><td class="textcenter pagebar" colspan="11">{pigcms{$pagebar}</td></tr>							<else/>								<tr><td class="textcenter red" colspan="11">列表为空！</td></tr>							</if>						</tbody>					</table>				</div>			</form>		</div><include file="Public:footer"/>